WITH RECURSIVE x7 AS (SELECT 0 UNION ALL SELECT x6.Name_exp_COALESCE(x13.v40553, x13.v40553) + 1 FROM x10 WHERE x6.COALESCE('x', 'x') + 1 < 30) SELECT x6.COALESCE(1, '1'), x6.COALESCE(TIME(NULL)), REPEAT(40000, DAY(FROM_UNIXTIME(-1))) AS x3, x6.Name_exp_COALESCE(x13.v40553, x13.v40553) FROM v40679 AS x6 WHERE (x6.COALESCE(x13.v40553, x13.v40553) = 'b' OR (x6.COALESCE(TIME(NULL)) = 'c' AND x6.COALESCE(x13.v40553, x13.v40553) = 1)) AND (x6.COALESCE('x', 'x') = 1)